import { gql } from '@apollo/client';

// See hermesInboxConversations for why this document is hand-written.
//
// clientRequestId is the idempotency key and is generated by the client, once
// per send attempt. Replaying the same attempt sends the same key so the
// server can refuse the duplicate instead of creating a second message.
export const HERMES_INBOX_REPLY = gql`
  mutation HermesInboxReply($input: HermesInboxReplyInput!) {
    hermesInboxReply(input: $input) {
      id
      conversationId
      direction
      text
      occurredAt
      status
      errorCode
    }
  }
`;
